import java.util.Arrays; class Solution { public int maxProfit(int k, int[] p) { int n = p.length; if (n == 0 || k == 0) return 0; if (k >= n / 2) { int ans = 0; for (int i = 1; i < n; i++) ans += Math.max(p[i] - p[i - 1], 0); return ans; } int[] buy = new int[k + 1], sell = new int[k + 1]; Arrays.fill(buy, Integer.MAX_VALUE); for (int price : p) for (int t = 1; t <= k; t++) { buy[t] = Math.min(buy[t], price - sell[t - 1]); sell[t] = Math.max(sell[t], price - buy[t]); } return sell[k]; } }
